import { useState } from "react";
import { createRoot } from "react-dom/client";
const ESTADOS = ["pendiente", "en ruta", "entregado"];
const INICIAL = [
  { id: 1, destino: "Avellaneda", estado: "pendiente" },
  { id: 2, destino: "San Martín", estado: "en ruta" },
  { id: 3, destino: "La Plata", estado: "entregado" },
  { id: 4, destino: "Quilmes", estado: "pendiente" },
  { id: 5, destino: "Tigre", estado: "en ruta" },
  { id: 6, destino: "Morón", estado: "pendiente" },
];
function Tablero() {
  const [envios, setEnvios] = useState(INICIAL);
  const [filtro, setFiltro] = useState("todos");
  const visibles = envios.filter((e) => filtro === "todos" || e.estado === filtro);
  const entregados = envios.filter((e) => e.estado === "entregado").length;
  const avanzar = (id) =>
    setEnvios(envios.map((e) => e.id === id ? { ...e, estado: ESTADOS[ESTADOS.indexOf(e.estado) + 1] } : e));
  return (
    <>
      <select value={filtro} onChange={(ev) => setFiltro(ev.target.value)}>
        {["todos", ...ESTADOS].map((o) => <option key={o} value={o}>{o}</option>)}
      </select>
      <ul>
        {visibles.map((e) => (
          <li key={e.id}>
            {e.destino}: {e.estado}{" "}
            <button disabled={e.estado === "entregado"} onClick={() => avanzar(e.id)}>avanzar</button>
          </li>
        ))}
      </ul>
      <p>Entregados: {entregados} de {envios.length}</p>
    </>
  );
}
createRoot(document.getElementById("app")).render(<Tablero />);

const criterios = ["equipo", "ecosistema", "peso", "longevidad", "costoDeCambio"];
const opciones = {
  "React + Next":  [5, 5, 2, 5, 3],
  "Vue":           [3, 4, 4, 4, 3],
  "Angular":       [2, 4, 3, 5, 2],
  "Svelte":        [2, 3, 5, 3, 3],
  "HTML + JS":     [4, 1, 5, 4, 5],
};
const pesos = {
  "Equipo de 3 que ya usa React": [5, 4, 1, 3, 3],
  "Una persona, sitio chico":     [2, 1, 4, 2, 4],
};
for (const [caso, w] of Object.entries(pesos)) {
  const total = w.reduce((a, b) => a + b, 0);
  const filas = Object.entries(opciones).map(([n, s]) => [n, s.reduce((acc, x, i) => acc + x * w[i], 0) / total]);
  filas.sort((a, b) => b[1] - a[1]);
  console.log(caso + ":");
  for (const [n, v] of filas) console.log("  " + n.padEnd(14) + v.toFixed(2));
}
